export interface ResizablePanelConfig {
  minSize?: number; // percentage, default 10
  maxSize?: number; // percentage, default 90
  collapsible?: boolean;
  collapsedSize?: number; // percentage when collapsed, default 0
  defaultCollapsed?: boolean;
}

export interface ResizableContextValue {
  sizes: number[];
  collapsed: boolean[];
  direction: "horizontal" | "vertical";
  containerRef: React.RefObject<HTMLDivElement | null>;
  // Imperative resize — called by handle during drag (direct DOM write)
  setSizeDirect: (index: number, size: number) => void;
  // Called on drag end — commits to React state
  commitSizes: (sizes: number[]) => void;
  toggleCollapse: (panelIndex: number) => void;
  panelConfigs: ResizablePanelConfig[];
}

"use client";

import * as React from "react";
import type { ResizableContextValue } from "./types";

export const ResizableCtx = React.createContext<ResizableContextValue | null>(
  null,
);

export function useResizable(): ResizableContextValue {
  const ctx = React.useContext(ResizableCtx);
  if (!ctx) throw new Error("useResizable must be used inside ResizableRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { ResizableCtx } from "./resizable-context";
import type { ResizablePanelConfig, ResizableContextValue } from "./types";
import { cn } from "@/lib/utils";

export interface ResizableRootProps {
  defaultSizes: number[]; // must sum to 100
  direction?: "horizontal" | "vertical";
  panelConfigs?: ResizablePanelConfig[];
  onResize?: (sizes: number[]) => void;
  children: React.ReactNode;
  className?: string;
}

export function ResizableRoot({
  defaultSizes,
  direction = "horizontal",
  panelConfigs = [],
  onResize,
  children,
  className,
}: ResizableRootProps) {
  const [sizes, setSizes] = React.useState<number[]>(defaultSizes);
  const [collapsed, setCollapsed] = React.useState<boolean[]>(() =>
    panelConfigs.map((c) => c.defaultCollapsed ?? false),
  );
  const containerRef = React.useRef<HTMLDivElement>(null);

  // Write sizes as CSS vars directly — used during drag (no re-render)
  function writeCssVars(s: number[]) {
    const el = containerRef.current;
    if (!el) return;
    s.forEach((size, i) => {
      el.style.setProperty(`--panel-${i}`, `${size}%`);
    });
  }

  // Initialize CSS vars when sizes state changes
  React.useLayoutEffect(() => {
    writeCssVars(sizes);
  }, [sizes]);

  const setSizeDirect = React.useCallback((index: number, size: number) => {
    // Direct DOM write — bypasses React entirely
    const el = containerRef.current;
    if (!el) return;
    el.style.setProperty(`--panel-${index}`, `${size}%`);
  }, []);

  const commitSizes = React.useCallback(
    (next: number[]) => {
      setSizes(next);
      onResize?.(next);
    },
    [onResize],
  );

  const toggleCollapse = React.useCallback(
    (panelIndex: number) => {
      const config = panelConfigs[panelIndex];
      if (!config?.collapsible) return;
      setCollapsed((prev) => {
        const next = [...prev];
        next[panelIndex] = !prev[panelIndex];
        return next;
      });
    },
    [panelConfigs],
  );

  const ctx: ResizableContextValue = {
    sizes,
    collapsed,
    direction,
    containerRef,
    setSizeDirect,
    commitSizes,
    toggleCollapse,
    panelConfigs,
  };

  return (
    <ResizableCtx.Provider value={ctx}>
      <div
        ref={containerRef}
        className={cn(
          "flex overflow-hidden",
          direction === "horizontal" ? "flex-row" : "flex-col",
          className,
        )}
      >
        {children}
      </div>
    </ResizableCtx.Provider>
  );
}

ResizableRoot.displayName = "ResizableRoot";

"use client";

import * as React from "react";
import { useResizable } from "./resizable-context";
import { cn } from "@/lib/utils";

export interface ResizablePanelProps {
  index: number;
  children: React.ReactNode;
  className?: string;
}

export function ResizablePanel({
  index,
  children,
  className,
}: ResizablePanelProps) {
  const { direction, collapsed, panelConfigs } = useResizable();
  const config = panelConfigs[index];
  const isCollapsed = collapsed[index] ?? false;

  const sizeVar = `var(--panel-${index}, ${100 / 3}%)`;

  return (
    <div
      className={cn("overflow-hidden min-w-0 min-h-0", className)}
      style={{
        [direction === "horizontal" ? "width" : "height"]: isCollapsed
          ? `${config?.collapsedSize ?? 0}%`
          : sizeVar,
        flex: "0 0 auto",
        transition: isCollapsed
          ? "width 200ms ease, height 200ms ease"
          : undefined,
      }}
    >
      {children}
    </div>
  );
}

ResizablePanel.displayName = "ResizablePanel";

"use client";

import * as React from "react";
import { useResizable } from "./resizable-context";
import { cn } from "@/lib/utils";

export interface ResizableHandleProps {
  /** Which gap this handle controls: between panel[index] and panel[index+1] */
  index: number;
  className?: string;
}

export function ResizableHandle({ index, className }: ResizableHandleProps) {
  const {
    sizes,
    direction,
    containerRef,
    setSizeDirect,
    commitSizes,
    panelConfigs,
  } = useResizable();
  const handleRef = React.useRef<HTMLDivElement>(null);
  const dragState = React.useRef<{
    startPointer: number;
    startSizeA: number;
    startSizeB: number;
    containerSize: number;
  } | null>(null);

  const configA = panelConfigs[index];
  const configB = panelConfigs[index + 1];
  const minA = configA?.minSize ?? 5;
  const minB = configB?.minSize ?? 5;
  const maxA = configA?.maxSize ?? 95;
  const maxB = configB?.maxSize ?? 95;

  function onPointerDown(e: React.PointerEvent) {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);

    const containerEl = containerRef.current;
    if (!containerEl) return;

    const rect = containerEl.getBoundingClientRect();
    const containerSize = direction === "horizontal" ? rect.width : rect.height;

    dragState.current = {
      startPointer: direction === "horizontal" ? e.clientX : e.clientY,
      startSizeA: sizes[index],
      startSizeB: sizes[index + 1],
      containerSize,
    };
  }

  function onPointerMove(e: React.PointerEvent) {
    if (!dragState.current || e.buttons !== 1) return;

    const { startPointer, startSizeA, startSizeB, containerSize } =
      dragState.current;
    const pointer = direction === "horizontal" ? e.clientX : e.clientY;
    const deltaPercent = ((pointer - startPointer) / containerSize) * 100;

    let newA = Math.max(minA, Math.min(maxA, startSizeA + deltaPercent));
    let newB = Math.max(minB, Math.min(maxB, startSizeB - deltaPercent));

    // Clamp so they don't exceed their combined original size
    const total = startSizeA + startSizeB;
    if (newA + newB > total) {
      newA = total - newB;
    }

    // Direct DOM write — zero React re-renders during drag
    setSizeDirect(index, newA);
    setSizeDirect(index + 1, newB);
  }

  function onPointerUp(e: React.PointerEvent) {
    if (!dragState.current) return;

    const { startPointer, startSizeA, startSizeB, containerSize } =
      dragState.current;
    const pointer = direction === "horizontal" ? e.clientX : e.clientY;
    const deltaPercent = ((pointer - startPointer) / containerSize) * 100;

    let newA = Math.max(minA, Math.min(maxA, startSizeA + deltaPercent));
    let newB = Math.max(minB, Math.min(maxB, startSizeB - deltaPercent));
    const total = startSizeA + startSizeB;
    if (newA + newB > total) newA = total - newB;

    // Commit to React state (one re-render total, at the end of drag)
    const next = [...sizes];
    next[index] = newA;
    next[index + 1] = newB;
    commitSizes(next);

    dragState.current = null;
  }

  return (
    <div
      ref={handleRef}
      role="separator"
      aria-orientation={direction === "horizontal" ? "vertical" : "horizontal"}
      className={cn(
        "group relative flex-shrink-0 flex items-center justify-center",
        "bg-transparent hover:bg-border/60 active:bg-primary/80",
        "transition-colors duration-100 cursor-col-resize select-none",
        direction === "horizontal"
          ? "w-1 cursor-col-resize"
          : "h-1 cursor-row-resize",
        className,
      )}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
    >
      {/* Visual grip dots */}
      <div
        className={cn(
          "flex gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity",
          direction === "horizontal" ? "flex-col" : "flex-row",
        )}
      >
        {Array.from({ length: 3 }).map((_, i) => (
          <div
            key={i}
            className="w-0.5 h-0.5 rounded-full bg-muted-foreground/50"
          />
        ))}
      </div>
    </div>
  );
}

ResizableHandle.displayName = "ResizableHandle";

export { ResizableRoot } from "./resizable-root";
export { ResizablePanel } from "./resizable-panel";
export { ResizableHandle } from "./resizable-handle";
export { useResizable } from "./resizable-context";
export type { ResizablePanelConfig } from "./types";
export type { ResizableRootProps } from "./resizable-root";
